#!/usr/bin/env python3
"""Spring quarter 2025 shipped-orders reconciliation (working script, not a deliverable).

Fetches every page of /orders by following "next", keeps every request going through token
expiry, rate limits and transient errors, de-duplicates by order id, keeps exact status
"shipped" with placed_at converted to UTC in [1 Mar 2025, 1 Jun 2025), looks up each
qualifying customer once, and rounds each order's discounted amount half up to a whole cent.
"""

import email.utils
import http.client
import json
import os
import re
import sys
import time
import urllib.error
import urllib.parse
import urllib.request
from collections import Counter
from datetime import datetime, timezone
from decimal import ROUND_HALF_UP, Decimal

BASE = "http://localhost:8080"
DATA_DIR = "/tmp/shipped-recon-data"
RAW_DIR = os.path.join(DATA_DIR, "raw")
RESULT_PATH = "/workspace/result.json"
REGIONS = ("north", "south", "east", "west")
RANGE_START = datetime(2025, 3, 1, tzinfo=timezone.utc)  # inclusive
RANGE_END = datetime(2025, 6, 1, tzinfo=timezone.utc)  # exclusive, i.e. 31 May 2025 is the last day in
PAGE_SIZE = 50
MAX_ATTEMPTS = 25

os.makedirs(RAW_DIR, exist_ok=True)
EVENTS = open(os.path.join(DATA_DIR, "events.log"), "a", encoding="utf-8")
token = None


def log(message):
    line = f"{datetime.now(timezone.utc):%H:%M:%S} {message}"
    print(line, file=sys.stderr, flush=True)
    EVENTS.write(line + "\n")
    EVENTS.flush()


def send(method, path, auth=True):
    headers = {"Authorization": f"Bearer {token}"} if auth else {}
    request = urllib.request.Request(urllib.parse.urljoin(BASE, path), method=method, headers=headers)
    try:
        with urllib.request.urlopen(request, timeout=30) as response:
            return response.status, response.headers, response.read()
    except urllib.error.HTTPError as error:
        return error.code, error.headers, error.read()


def wait_seconds(headers, body):
    """Seconds a 429 asks us to wait: the Retry-After header, else a number in the body."""
    retry_after = headers.get("Retry-After")
    if retry_after is not None:
        try:
            return float(retry_after) + 1
        except ValueError:
            when = email.utils.parsedate_to_datetime(retry_after)
            return max(0.0, when.timestamp() - time.time()) + 1
    text = body.decode("utf-8", "replace")
    match = re.search(r"(?:retry|wait)\D{0,40}?(\d+(?:\.\d+)?)", text, re.IGNORECASE) or re.search(
        r"(\d+(?:\.\d+)?)\s*(?:s|sec|secs|seconds)\b", text, re.IGNORECASE
    )
    if match:
        return float(match.group(1)) + 1
    log(f"429 with no readable wait time; headers={list(headers.items())} body={text[:200]!r}; waiting 60s")
    return 60.0


def call(path, method="GET", auth=True, definitive=()):
    """Return (status, json) for a 200 or for a status listed in `definitive`.

    Any other failure repeats the same request: 401/403 fetches a new token, 429 waits the
    stated time, anything else backs off and tries again.
    """
    for attempt in range(1, MAX_ATTEMPTS + 1):
        try:
            status, headers, body = send(method, path, auth)
        except (OSError, http.client.HTTPException) as error:
            log(f"{method} {path} attempt {attempt}: transport error {error!r}")
            time.sleep(min(2**attempt, 30))
            continue
        if status == 200:
            try:
                return status, json.loads(body)
            except ValueError:
                log(f"{method} {path} attempt {attempt}: 200 with unparseable body {body[:200]!r}")
                time.sleep(min(2**attempt, 30))
                continue
        if status in definitive:
            return status, None
        if status in (401, 403):
            log(f"{method} {path} attempt {attempt}: HTTP {status} {body[:200]!r}; fetching a new token")
            refresh_token()
        elif status == 429:
            seconds = wait_seconds(headers, body)
            log(f"{method} {path} attempt {attempt}: rate limited; waiting {seconds:.0f}s")
            time.sleep(seconds)
        else:
            log(f"{method} {path} attempt {attempt}: HTTP {status} {body[:200]!r}; retrying")
            time.sleep(min(2**attempt, 30))
    raise RuntimeError(f"{method} {path} still failing after {MAX_ATTEMPTS} attempts")


def refresh_token():
    global token
    _, payload = call("/token", method="POST", auth=False)
    token = payload["token"]
    log("token refreshed")


def fetch_orders():
    pages = []
    path = "/orders?page=1"
    while path is not None:
        number = len(pages) + 1
        _, page = call(path)
        if page["page"] != number:
            raise RuntimeError(f"requested page {number}, server returned page {page['page']}")
        with open(os.path.join(RAW_DIR, f"orders-page-{number:03d}.json"), "w", encoding="utf-8") as f:
            json.dump(page, f)
        pages.append(page)
        if page["next"] is not None and page["next"] != f"/orders?page={number + 1}":
            log(f"unexpected next link after page {number}: {page['next']!r}")
        path = page["next"]

    total_pages = pages[0]["total_pages"]
    if any(p["total_pages"] != total_pages for p in pages) or total_pages != len(pages):
        raise RuntimeError(f"page count mismatch: total_pages={total_pages}, fetched {len(pages)}")
    for number, page in enumerate(pages, start=1):
        count = len(page["items"])
        if (number < len(pages) and count != PAGE_SIZE) or not 0 < count <= PAGE_SIZE:
            raise RuntimeError(f"page {number} has {count} items")
    return pages


def parse_utc(text):
    stamp = datetime.fromisoformat(text.replace("Z", "+00:00"))
    if stamp.tzinfo is None:
        raise ValueError(f"placed_at has no offset: {text!r}")
    return stamp.astimezone(timezone.utc)


def discounted_cents(amount, pct):
    """amount * (100 - pct) / 100, rounded half up to a whole cent, in integer arithmetic."""
    quotient, remainder = divmod(amount * (100 - pct), 100)
    return quotient + 1 if remainder >= 50 else quotient


def discounted_check(amount, pct):
    exact = Decimal(amount) * (100 - pct) / 100
    return int(exact.quantize(Decimal(1), rounding=ROUND_HALF_UP))


def main():
    refresh_token()
    pages = fetch_orders()
    listings = [order for page in pages for order in page["items"]]

    first = {}
    conflicts = []
    repeats = 0
    for order in listings:
        seen = first.get(order["id"])
        if seen is None:
            first[order["id"]] = order
        else:
            repeats += 1
            if seen != order:
                conflicts.append((seen, order))

    print(f"pages: {len(pages)}  listings: {len(listings)}  distinct ids: {len(first)}  repeats discarded: {repeats}")
    print("statuses:", dict(Counter(o["status"] for o in first.values())))
    print("placed_at offset forms:", dict(Counter(re.search(r"(Z|[+-]\d{2}:\d{2})$", o["placed_at"]).group(1) if re.search(r"(Z|[+-]\d{2}:\d{2})$", o["placed_at"]) else o["placed_at"] for o in first.values())))
    if conflicts:
        for seen, order in conflicts[:5]:
            print("CONFLICT:", seen, order)
        raise RuntimeError(f"{len(conflicts)} repeated listings differ from the first listing of that id")

    shipped = [o for o in first.values() if o["status"] == "shipped"]
    qualifying = [o for o in shipped if RANGE_START <= parse_utc(o["placed_at"]) < RANGE_END]
    local_date_rule = [o for o in shipped if "2025-03-01" <= o["placed_at"][:10] <= "2025-05-31"]
    print(f"shipped: {len(shipped)}  in range (UTC): {len(qualifying)}  in range by local date (diagnostic only): {len(local_date_rule)}")

    customers = {}
    missing = []
    for cid in sorted({o["customer_id"] for o in qualifying}):
        status, customer = call(f"/customers/{cid}", definitive=(404,))
        if status == 404:
            missing.append(cid)
            continue
        pct = customer["discount_pct"]
        if customer["id"] != cid or customer["region"] not in REGIONS or type(pct) is not int or not 0 <= pct <= 100:
            raise RuntimeError(f"unexpected customer record: {customer}")
        customers[cid] = customer
    if missing:
        raise RuntimeError(f"qualifying orders reference unknown customers: {missing}")

    totals = {region: 0 for region in REGIONS}
    ties = 0
    for order in qualifying:
        customer = customers[order["customer_id"]]
        amount, pct = order["amount_cents"], customer["discount_pct"]
        if type(amount) is not int or amount < 0:
            raise RuntimeError(f"unexpected amount_cents: {order}")
        if (amount * (100 - pct)) % 100 == 50:
            ties += 1
        cents = discounted_cents(amount, pct)
        if cents != discounted_check(amount, pct):
            raise RuntimeError(f"rounding cross-check failed for {order}")
        totals[customer["region"]] += cents

    result = {
        "total_cents": sum(totals.values()),
        "order_count": len(qualifying),
        "duplicates_skipped": repeats,
        "by_region": totals,
    }
    print(json.dumps(result, indent=2))
    print(f"half-cent ties: {ties}  customers looked up: {len(customers)}")

    with open(RESULT_PATH, "w", encoding="utf-8") as f:
        json.dump(result, f, indent=2)
        f.write("\n")
    log(f"wrote {RESULT_PATH}")


if __name__ == "__main__":
    main()

