    for number, page in enumerate(pages, start=1):
        count = len(page["items"])
        if (number < len(pages) and count != PAGE_SIZE) or not 0 < count <= PAGE_SIZE:
            raise RuntimeError(f"page {number} has {count} items")
    return pages


def offset_form(text):
    match = re.search(r"(Z|[+-]\d{2}:\d{2})$", text)
    return match.group(1) if match else text


def parse_utc(text):
    stamp = datetime.fromisoformat(text.replace("Z", "+00:00"))
    if stamp.tzinfo is None:
        raise ValueError(f"placed_at has no offset: {text!r}")
    return stamp.astimezone(timezone.utc)


def discounted_cents(amount, pct):
    """amount * (100 - pct) / 100, rounded half up to a whole cent, in integer arithmetic."""
    quotient, remainder = divmod(amount * (100 - pct), 100)
    return quotient + 1 if remainder >= 50 else quotient


def discounted_check(amount, pct):
    exact = Decimal(amount) * (100 - pct) / 100
    return int(exact.quantize(Decimal(1), rounding=ROUND_HALF_UP))


def main():
    refresh_token()
    pages = fetch_orders()
    listings = [order for page in pages for order in page["items"]]

    first = {}
    conflicts = []
    repeats = 0
    for order in listings:
        seen = first.get(order["id"])
        if seen is None:
            first[order["id"]] = order
        else:
            repeats += 1
            if seen != order:
                conflicts.append((seen, order))

    print(f"pages: {len(pages)}  listings: {len(listings)}  distinct ids: {len(first)}  repeats discarded: {repeats}")
    print("statuses:", dict(Counter(o["status"] for o in first.values())))
    print("placed_at offset forms:", dict(Counter(offset_form(o["placed_at"]) for o in first.values())))
    if conflicts:
        for seen, order in conflicts[:5]:
            print("CONFLICT:", seen, order)
        raise RuntimeError(f"{len(conflicts)} repeated listings differ from the first listing of that id")

    shipped = [o for o in first.values() if o["status"] == "shipped"]
    qualifying = [o for o in shipped if RANGE_START <= parse_utc(o["placed_at"]) < RANGE_END]
    local_date_rule = [o for o in shipped if "2025-03-01" <= o["placed_at"][:10] <= "2025-05-31"]
    print(f"shipped: {len(shipped)}  in range (UTC): {len(qualifying)}  in range by local date (diagnostic only): {len(local_date_rule)}")

    customers = {}
    missing = []
    for cid in sorted({o["customer_id"] for o in qualifying}):
        status, customer = call(f"/customers/{cid}", definitive=(404,))
        if status == 404:
            missing.append(cid)
            continue
        pct = customer["discount_pct"]
        if customer["id"] != cid or customer["region"] not in REGIONS or type(pct) is not int or not 0 <= pct <= 100:
            raise RuntimeError(f"unexpected customer record: {customer}")
        customers[cid] = customer
    if missing:
        raise RuntimeError(f"qualifying orders reference unknown customers: {missing}")

    totals = {region: 0 for region in REGIONS}
    ties = 0
    for order in qualifying:
        customer = customers[order["customer_id"]]
        amount, pct = order["amount_cents"], customer["discount_pct"]
        if type(amount) is not int or amount < 0:
            raise RuntimeError(f"unexpected amount_cents: {order}")
        if (amount * (100 - pct)) % 100 == 50:
            ties += 1
        cents = discounted_cents(amount, pct)
        if cents != discounted_check(amount, pct):
            raise RuntimeError(f"rounding cross-check failed for {order}")
        totals[customer["region"]] += cents

    result = {
        "total_cents": sum(totals.values()),
        "order_count": len(qualifying),
        "duplicates_skipped": repeats,
        "by_region": totals,
    }
    print(json.dumps(result, indent=2))
    print(f"half-cent ties: {ties}  customers looked up: {len(customers)}")

    with open(RESULT_PATH, "w", encoding="utf-8") as f:
        json.dump(result, f, indent=2)
        f.write("\n")
    log(f"wrote {RESULT_PATH}")


if __name__ == "__main__":
    main()
